class ProposeContext(BaseModel):
    """
    `signal_llm`'s request (`external.propose`): the context to propose the document's
    metadata from. No prompt: the consumer makes its own. Lekto checks the answer as a
    language model's: its structure at once (422), its values against the text and the other
    signals; a contact turns green only with a second signal or hard evidence.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    contract: Annotated[Literal["propose-ext-1"], Field(title="Contract")] = "propose-ext-1"
    task: ModelCallTask
    document: ModelCallDocument
    contacts: Annotated[list[ListedContact], Field(title="Contacts")]
    """
    The 20 contacts the text names most.
    """
    document_types: Annotated[list[ListedDocumentType], Field(title="Document Types")]
    fields: Annotated[dict[str, ListedField], Field(title="Fields")]
    """
    The fields that may be read, by key.
    """
    general_fields: Annotated[list[str], Field(title="General Fields")]
    """
    The keys of the fields of every document.
    """
    tags: Annotated[list[str], Field(title="Tags")]
    spaces: Annotated[list[ListedSpace], Field(title="Spaces")]
    """
    Empty with fewer than two spaces to choose.
    """
    answer_schema: Annotated[dict[str, Any], Field(title="Answer Schema")]
    """
    The JSON Schema of `answer` (strict: every property required, nothing else allowed, null for what the document does not show), built from the master data of the moment; the rules for each value are its `description`. Usable as structured output.
    """


