class WebhookCreate(BaseModel):
    model_config = ConfigDict(
        extra="forbid",
    )
    name: Annotated[str, Field(max_length=100, min_length=1, title="Name")]
    """
    Shown in lists.
    """
    url: Annotated[str, Field(max_length=2000, title="Url")]
    """
    Where Lekto sends the events (POST). `http` or `https`; targets in the own network are fine. Redirects are not followed.
    """
    event_types: Annotated[list[str] | None, Field(max_length=13, title="Event Types")] = []
    """
    Event types: `document.confirmed`, `document.deleted`, `document.filed`, `document.lane_changed`, `document.moved`, `document.node_completed`, `document.node_deferred`, `document.node_delegated`, `document.node_started`, `document.received`, `document.review_required`, `document.updated`, or `*` for all, also future ones. None: the webhook serves rules only.
    """
    active: Annotated[bool | None, Field(title="Active")] = True
    signed: Annotated[bool | None, Field(title="Signed")] = True
    """
    With a secret that signs every request (`webhook-signature`, Standard Webhooks), shown once in the answer. Without: no signature, e.g. for a receiver that checks a header instead.
    """
    headers: Annotated[
        list[HeaderIn] | None, Field(max_length=20, title="Headers", validate_default=True)
    ] = []
    """
    Headers of the webhook's own, sent with every request (at most 20), e.g. `Authorization` for a token the receiver checks. Lekto sets `content-type`, `content-length`, `host`, `connection`, `transfer-encoding` and the headers beginning with `webhook-` or `lekto-` itself; those are refused. The values are stored encrypted and never shown again; the names are.
    """
    body: Annotated[
        Literal["thin", "full", "template"] | Unknown | None, Field(title="BodyFormat")
    ] = "thin"
    """
    What a request carries: `thin`, the event (`id`, `type`, `occurred_at`, `document_id`); `full`, the event and `document` as it is when the request goes (title, contact, type, topic, tags, date, space, lane, the fields with a value by key, `link` into the web UI); `template`, the JSON `body_template` makes of them.
    """
    body_template: Annotated[BodyTemplate | None, Field(title="Body Template")] = None
    """
    For `body: template`: Liquid that makes JSON. It sees what a rule's template sees (`title`, `contact`, `field.<key>`, ...), `event` (`type`, `id`, `occurred_at`), `document_id`, `lane` and `link`; in a rule's request `rule` (`id`, `name`), in a task's also `task` (`id`, `callback`, `token`, `deadline`) and `steps.<name>`. The filter `json` writes a value as JSON (`{{ title | json }}`), `| default: nil` a missing one as `null`.
    """
    max_open_tasks: Annotated[int | None, Field(ge=1, le=64, title="Max Open Tasks")] = 4
    """
    How many tasks (requests that expect an answer, e.g. a rule step that asks) the webhook takes at the same time, 1 to 64; more wait in Lekto, and their time to answer starts when they are sent.
    """
    model_call: WebhookModelCallIn | None = None
    """
    The request to the language model the webhook takes over, for every document: `propose` (the proposal of `signal_llm`) or `extract` (the values of the fields the proposal did not give, in `fields`). Lekto sends it as a task with a fixed contract (`external.propose`, `external.extract` under `webhooks`), whatever `body` says. Only an admin gives it to an admin's webhook; of the active webhooks at most one serves each kind (409). null: none.
    """


class WebhookCreated(BaseModel):
    id: Annotated[UUID, Field(title="Id")]
