type Identifiers = Annotated[list[IdentifierIn], Field(max_length=100, title="Identifiers")]
"""
Values the contact's documents carry: IBAN, VAT number, customer (or contract) number, the personnel number at an employer (without leading zeros), the domain of its e-mail and web addresses. Unique across contacts; found in a document, they are evidence for the contact. The identifiers entered by hand: a learned one given here becomes one entered by hand.
"""


type RejectedIdentifiers = Annotated[
    list[IdentifierIn], Field(max_length=100, title="Rejected Identifiers")
]
"""
The rejected identifiers: a learned one given here no longer counts, and training does not learn it again; one left out may be learned again.
"""


