class MailRuleCreate(BaseModel):
    """
    A new mail rule of a mailbox; what is left out gets the default (priority 100, no
    conditions: every mail, takes the attachments and the text, leaves the mail, active).
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    priority: Annotated[Priority | None, Field(title="Priority")] = None
    """
    Higher first.
    """
    conditions: Annotated[
        AllGroupMailConditionBodyInput | AnyGroupMailConditionBodyInput | None,
        Field(title="Conditions"),
    ] = None
    """
    A tree as a document rule's: a group of `all` or `any`, `not` turns it around; its items are conditions or groups again, nested at most 5 deep, at most 50 conditions. Fields: `sender`, `recipient` (To or Cc), `to`, `cc` and `subject` with `contains`, `is`, `starts_with`, `ends_with` (an address or a name, regardless of case); `folder` with `is`; `attachments` with `present` or `missing` (attachments Lekto takes); `importance` with `is` (`high`, `normal`, `low`); `keyword` with `contains` (an IMAP keyword, regardless of case), `present` or `missing`; `flag` with `present`, `missing` or `is` (a colour: `red`, `orange`, `yellow`, `green`, `blue`, `purple`, `gray`). Null: every mail.
    """
    parts: Literal["all", "attachments", "text", "nothing"] | Unknown | None = None
    """
    What it takes: `all` (the attachments and the text), `attachments`, `text`, `nothing`.
    """
    user_id: Annotated[UUID | None, Field(title="User Id")] = None
    """
    Whom it takes the mail for.
    """
    space_id: Annotated[UUID | None, Field(title="Space Id")] = None
    """
    A space the person files into; null: their personal one.
    """
    text_type_id: Annotated[UUID | None, Field(title="Text Type Id")] = None
    """
    The document type of the mail's text; null: Lekto decides.
    """
    after: Annotated[After | None, Field(title="After")] = None
    """
    The steps on the mail on the server once taken, in order: `read`, `unread`, `flag` (with `value` a colour: `red`, `orange`, `yellow`, `green`, `blue`, `purple`, `gray`, as Apple Mail shows it), `unflag`, `add_keyword` and `remove_keyword` (with `value` an IMAP keyword), then at most one last: `move` (with `value` the folder) or `trash`. None twice; at most 10. A step the server refuses is noted at the mailbox; the next ones go on.
    """
    enabled: Annotated[bool | None, Field(title="Enabled")] = None
    mailbox_id: Annotated[UUID, Field(title="Mailbox Id")]
    name: Annotated[str, Field(max_length=200, min_length=1, title="Name")]


